#include <omp.h>
#include <array>
#include <cstddef>
#include <vector>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    bins.fill(0);

    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(x.size());

    #pragma omp parallel default(none) shared(x, bins, n)
    {
        std::array<size_t, 10> local_bins{};
        local_bins.fill(0);

        #pragma omp for nowait
        for (std::ptrdiff_t i = 0; i < n; ++i) {
            const double v = x[static_cast<std::size_t>(i)];

            int bin = static_cast<int>(v / 10.0);
            if (bin < 0) {
                bin = 0;
            } else if (bin > 9) {
                // Places 100.0 into the last bin, and safely clamps any
                // out-of-range value to the valid bin range.
                bin = 9;
            }

            ++local_bins[static_cast<std::size_t>(bin)];
        }

        #pragma omp critical
        {
            for (std::size_t b = 0; b < bins.size(); ++b) {
                bins[b] += local_bins[b];
            }
        }
    }
}
